// zcode-acp quota-dock plugin v1 (seeded by zcode-acp-server, ADR-0021)
return {
  inject: ["tuiSlots", "acpSessionConfig", "acpSessionStats"],
  apply: (ctx) => {
    let panel
    let quotaText = null
    let context = null
    const compactSize = (n) => {
      if (n >= 1000000) return (Math.round(n / 100000) / 10) + "M"
      if (n >= 1000) return Math.round(n / 1000) + "K"
      return String(n)
    }
    const readQuota = () => {
      const options = ctx.acpSessionConfig.list()
      const found = (options || []).filter((o) => o && o.id === "quota")[0]
      const v = found && typeof found.currentValue === "string" ? found.currentValue : null
      quotaText = v && v.length > 0 ? v : null
    }
    const readStats = () => {
      const cur = ctx.acpSessionStats.current ? ctx.acpSessionStats.current() : null
      const c = cur && cur.context ? cur.context : null
      context = c && typeof c.used === "number" && typeof c.size === "number" && c.size > 0 ? c : null
    }
    const nodes = () => {
      const parts = []
      if (context) parts.push("ctx " + (Math.round((context.used / context.size) * 1000) / 10) + "%/" + compactSize(context.size))
      if (quotaText) parts.push(quotaText)
      if (parts.length === 0) return []
      return [{ id: "zcode-acp-quota-gauge", kind: "generic", title: parts.join(" · "), body: "" }]
    }
    const render = () => { if (panel) { try { panel.update(nodes()) } catch (err) {} } }
    const stopSlot = ctx.tuiSlots.inject("conversation.composer.dock", () => {
      panel = ctx.tuiSlots.register({ name: "conversation.composer.dock", id: "zcode-acp-quota" }, nodes())
      return () => panel.dispose()
    })
    readQuota()
    readStats()
    const stopSub = ctx.acpSessionConfig.subscribe((snap) => { readQuota(); render() })
    let stopStats = null
    if (ctx.acpSessionStats.subscribe) stopStats = ctx.acpSessionStats.subscribe(() => { readStats(); render() })
    return () => { stopSub && stopSub(); stopStats && stopStats(); stopSlot && stopSlot() }
  },
}
